/** Radiographer worklist (STAT first, then by due time) — GET /api/v1/imaging/worklist (who may call: holders of imaging.order.update). */
export function worklistImaging(query?: { status?: "Ordered" | "Scheduled" | "InProgress" | "Completed" | null; modality?: "XRay" | "MRI" | "CT" | "Ultrasound" | "Doppler" | "Mammography" | "Fluoroscopy" | "Other" | null }): Promise<ImagingWorklistItemOut[]> {
  return api<ImagingWorklistItemOut[]>("GET", withQuery(`/imaging/worklist`, query), undefined);
}

/** Progress / cancel an imaging order — POST /api/v1/imaging/orders/{order_id}/status (who may call: holders of imaging.order.update). */
export function setStatusImagingOrders(order_id: number, body: ImagingStatusIn): Promise<ImagingOrderOut> {
  return api<ImagingOrderOut>("POST", `/imaging/orders/${order_id}/status`, body, { idempotent: true });
}

/** Link the PACS study (auto-find by accession if no ids given) — POST /api/v1/imaging/orders/{order_id}/link-study (who may call: holders of imaging.order.update). */
export function linkStudy(order_id: number, body: LinkIn): Promise<ImagingOrderLinkedOut> {
  return api<ImagingOrderLinkedOut>("POST", `/imaging/orders/${order_id}/link-study`, body, { idempotent: true });
}

/** Enter the radiology report (radiologist) — POST /api/v1/imaging/orders/{order_id}/report (who may call: holders of imaging.report.enter). */
export function reportImagingOrders(order_id: number, body: ReportIn): Promise<ImagingOrderOut> {
  return api<ImagingOrderOut>("POST", `/imaging/orders/${order_id}/report`, body, { idempotent: true });
}

